"""Reusable Streamlit UI pieces."""

from __future__ import annotations

import html

import pandas as pd
import streamlit as st

from config import DB_PATH, SEVERITIES
from dashboard.theme import SEVERITY_COLORS, STATUS_COLORS
from database import Database

INDICATOR_NOTE = (
    "Alerts are <b>detection indicators</b> generated by rules from your logs. "
    "They are <b>not confirmed attacks</b> and must be validated by an analyst. "
    "This tool never scans or blocks IP addresses."
)


@st.cache_resource
def get_db() -> Database:
    """One Database object per server process (it opens a connection per call)."""
    return Database(DB_PATH)


def page_header(title: str, subtitle: str) -> None:
    st.title(title)
    st.markdown(f"<div class='page-sub'>{html.escape(subtitle)}</div>", unsafe_allow_html=True)


def indicator_note() -> None:
    st.markdown(f"<div class='indicator-note'>⚠️ {INDICATOR_NOTE}</div>", unsafe_allow_html=True)
    st.write("")


def severity_badge(severity: str) -> str:
    color = SEVERITY_COLORS.get(severity, "#8b8b85")
    return f"<span class='sev-badge' style='background:{color}'>{html.escape(severity)}</span>"


def status_badge(status: str) -> str:
    color = STATUS_COLORS.get(status, "#8b8b85")
    return f"<span class='sev-badge' style='background:{color}'>{html.escape(status)}</span>"


def severity_cards(counts: dict[str, int]) -> None:
    """Four severity tiles: colour bar + text label + number."""
    cols = st.columns(len(SEVERITIES))
    for col, sev in zip(cols, SEVERITIES):
        col.markdown(
            f"<div class='sev-card' style='border-left-color:{SEVERITY_COLORS[sev]}'>"
            f"<div class='label'>{sev} alerts</div>"
            f"<div class='value'>{counts.get(sev, 0)}</div></div>",
            unsafe_allow_html=True,
        )


def empty_state(message: str) -> None:
    st.info(message + "  Go to **Upload Logs** to upload files or load the synthetic sample data.")


def alerts_table(df: pd.DataFrame, key: str, selectable: bool = False):
    """Prioritised alert table. Returns the selection event when selectable."""
    view = df[[
        "alert_id", "priority", "risk_score", "severity", "status", "rule_id", "rule_name",
        "source_ip", "username", "event_count", "timestamp",
    ]].copy()
    view["mitre"] = df["mitre"].apply(lambda ms: ", ".join(m["technique_id"] for m in ms) or "—")
    config = {
        "alert_id": st.column_config.TextColumn("Alert ID"),
        "priority": st.column_config.TextColumn("Priority", help="P1 = triage first (score ≥ 85)"),
        "risk_score": st.column_config.ProgressColumn("Risk", min_value=0, max_value=100, format="%d"),
        "severity": st.column_config.TextColumn("Severity"),
        "status": st.column_config.TextColumn("Status"),
        "rule_id": st.column_config.TextColumn("Rule"),
        "rule_name": st.column_config.TextColumn("Detection"),
        "source_ip": st.column_config.TextColumn("Source IP"),
        "username": st.column_config.TextColumn("User(s)"),
        "event_count": st.column_config.NumberColumn("Events"),
        "timestamp": st.column_config.DatetimeColumn("Time (UTC)", format="YYYY-MM-DD HH:mm:ss"),
        "mitre": st.column_config.TextColumn("MITRE"),
    }
    if selectable:
        return st.dataframe(view, hide_index=True, column_config=config, key=key,
                            on_select="rerun", selection_mode="single-row")
    st.dataframe(view, hide_index=True, column_config=config, key=key)
    return None


def open_investigation(alert_id: str) -> None:
    """Callback: jump to the Alert Investigation page for an alert."""
    st.session_state["selected_alert"] = alert_id
    st.session_state["nav"] = "Alert Investigation"
